seams.sql:
SELECT COUNT(*) AS seams,
  COUNT(*) FILTER (WHERE next_from <> valid_to + 1) AS bad_seams
FROM (
  SELECT valid_to, LEAD(valid_from) OVER (PARTITION BY customer_id ORDER BY valid_from) AS next_from
  FROM dim_customer
) WHERE next_from IS NOT NULL;

