fanoutTotal.sql:
SELECT SUM(f.amount) AS revenue
FROM fact_orders f
JOIN order_promotion_bridge b ON b.order_key = f.order_key;

weightedTotal.sql:
SELECT SUM(f.amount * b.weight) AS revenue
FROM fact_orders f
JOIN order_promotion_bridge b ON b.order_key = f.order_key;

